from pathlib import Path
import re
pages = [Path(p) for p in ('docs/adrs/0001-use-signed-session-cookies.md', 'docs/adrs/README.md', 'docs/architecture.md', 'docs/features/sessions.md', 'docs/runbooks/rotate-session-key.md', 'docs/runbooks/README.md')]
for page in pages:
    for target in re.findall(r'\]\(([^)]+)\)', page.read_text()):
        if '://' not in target and not target.startswith('#'):
            assert (page.parent / target.split('#', 1)[0]).exists(), (page, target)
print('All relative links in changed pages resolve.')
PY
